async function placeOrder(order: Order): Promise<void> {
	await db.transaction(async (tx) => {
		await tx.query("INSERT INTO orders (id, total) VALUES ($1, $2)", [order.id, order.total]);
		// Mesma transação: ou as duas linhas existem, ou nenhuma.
		await tx.query(
			"INSERT INTO outbox (event_id, type, payload) VALUES ($1, $2, $3)",
			[crypto.randomUUID(), "OrderPlaced", JSON.stringify({ orderId: order.id })],
		);
	});
}

// Um relay separado lê as linhas não publicadas da outbox,
// publica no broker e só então as marca como publicadas.

